changeSet.sql:
CREATE TABLE `r_job_category` (
                                  `id` int unsigned NOT NULL AUTO_INCREMENT,
                                  `category_name` varchar(50) NOT NULL,
                                  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `r_job_mode` (
                               `id` int unsigned NOT NULL AUTO_INCREMENT,
                               `mode_name` varchar(50) NOT NULL,
                               PRIMARY KEY (`id`)
 ) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `r_job_type` (
                              `id` int unsigned NOT NULL AUTO_INCREMENT,
                              `type_name` varchar(20) NOT NULL,
                              PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

alter table r_job
    modify customer_id bigint unsigned null comment '客户Id';

alter table r_job
    modify master_account_id bigint unsigned null comment '客户主账号Id';

alter table r_job
    add company_code varchar(32) default '' not null comment '公司code' after max_salary;

create index idx_company_code
    on r_job (company_code);

drop index idx_master_account_id on r_job;

ALTER TABLE r_candidate_job
    MODIFY COLUMN apply_status tinyint NOT NULL DEFAULT '0'
    COMMENT '简历申请状态(0:已提交;10:AI筛选;20:AI面试;30:人工审核;40:就绪;50:背景审核;99:拒绝)';

alter table r_leads_customer_company
    add central_company_id bigint null comment '注册时返回companyId' after central_manager_id;

create index idx_company_id
    on r_leads_customer_company (central_company_id);

alter table r_candidate
    alter column phone_number set default '';

alter table r_candidate
    alter column password set default '';

create index idx_candidate_id
    on r_candidate (candidate_id);

ALTER TABLE `r_points_operation_log`
MODIFY COLUMN `freeze_interview_type` TINYINT NOT NULL DEFAULT 0 COMMENT 'freeze interview type(0:video,1:audio)',
MODIFY COLUMN `actual_interview_type` TINYINT NULL COMMENT 'actual interview type(0:video,1:audio)';

alter table r_ai_vetted_result MODIFY overall_skill_assessment TEXT COMMENT '评价';
alter table r_ai_vetted_result_skill MODIFY skill_assessment TEXT COMMENT '评价';
ALTER TABLE r_ai_vetted_result_skill MODIFY skill_score tinyint NULL COMMENT '技能评分';
